// #endregion 🔖Header

// #region 🔖Renderer
// [🔬coda🖱️desktop💻renderer🔖renderer](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer)
// Electron renderer process that mounts the coda dashboard React app with window controls.
// MUST resolve the user identity before rendering the dashboard.
// MUST communicate with coda MCP server via the preload bridge.

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";

import { Tree, TreeItem } from "../../elements/ui";

import "./globals.css";

// #region 🔖Types
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types)
// TypeScript interfaces for coda domain models used in the renderer.
// Types MUST match the coda MCP server data structures.

declare global {
  interface Window {

          {currentPage === "events" && <EventsPage events={events} onClear={handleClearEvents} />}
        </main>
        {/* #endregion Content */}
      </div>
    </div>
  );
}

export default App;

export { OntologyTree, ValidationTree, getOntologyNodeDescriptor, getValidationNodeDescriptor };
export type { OntologyTreeNode, OntologyNodeKind, ValidationTreeNode, ValidationNodeKind, TruthValue, ValidationReport };

if (typeof document !== "undefined") {
  const rootElement = document.getElementById("root");
  if (rootElement) {
    createRoot(rootElement).render(
      <React.StrictMode>
        <App />
      </React.StrictMode>,
    );
  }
}

// #endregion 🔖App

// #endregion 🔖Renderer

