// Entry point for the Electron renderer process mounting the coda React app.

// #endregion 🔖Header

// #region 🔖Renderer
// [🔬coda🖱️desktop💻renderer🔖renderer](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer)
// Electron renderer process that mounts the coda dashboard React app with window controls.
// MUST resolve the user identity before rendering the dashboard.
// MUST communicate with coda MCP server via the preload bridge.

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";

import { Tree, TreeItem } from "../../elements/ui";

import "./globals.css";

// #region 🔖Types
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types)
// TypeScript interfaces for coda domain models used in the renderer.
// Types MUST match the coda MCP server data structures.

declare global {
  interface Window {
    windowControls: {
      minimize(): Promise<void>;
      maximize(): Promise<void>;
      close(): Promise<void>;
    };
    os: {
      getUserId(): Promise<string>;
    };
    coda: {
      call(method: string, params?: Record<string, unknown>): Promise<McpResponse>;
      fetch(uri: string): Promise<McpResponse>;
      tool(name: string, args: Record<string, unknown>): Promise<McpResponse>;
      getConnectionStatus(): Promise<boolean>;
      onEvent(callback: (event: CodaEvent) => void): () => void;
      onConnectionStatus(callback: (connected: boolean) => void): () => void;
    };
    dialog: {
      openFolder(): Promise<string | null>;
    };
    project: {
      getPath(): Promise<string | null>;
      open(folder: string): Promise<{ success: boolean; error?: string }>;
      create(name: string, folder: string): Promise<{ success: boolean; error?: string }>;
    };
  }
}

/**
 * An event pushed from the coda sidecar process.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️codaevent](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/CodaEvent)
 *MUST have event kind, data, and timestamp.
 **/
interface CodaEvent {
  event: string;
  data: Record<string, unknown>;
  timestamp: number;
}

/**
 * MCP JSON-RPC response wrapper.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️mcpresponse](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/McpResponse)
 *MUST contain either result or error.
 **/
interface McpResponse {
  jsonrpc: string;
  id: number;
  result?: {
    contents?: Array<{ uri: string; mimeType?: string; text?: string }>;
    content?: Array<{ type: string; text?: string }>;
  };
  error?: { code: number; message: string };
}

/**
 * A design measure available for fixing breaches.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️measure](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Measure)
 *MUST have id and description.
 **/
interface Measure {
  id: string;
  description: string;
}

/**
 * A platform with optional measure instructions.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️platform](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Platform)
 *MUST have an id.
 **/
interface Platform {
  id: string;
  measures?: Array<{
    id: string;
    instructions?: string;
    mcp?: {
      resources?: Array<{ id: string; instruction: string }>;
      tools?: Array<{ id: string; instruction: string; parameters?: Array<{ id: string; instruction: string }> }>;
    };
  }>;
}

/**
 * A clause within a compliance rule.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️clause](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Clause)
 *MUST have id and description.
 **/
interface Clause {
  id: string;
  description: string;
  status?: "compliant" | "violated" | "unknown";
  properties?: Array<{ id: string; value: string }>;
}

/**
 * A compliance rule belonging to a target.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️rule](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Rule)
 *MUST have id and description.
 **/
interface Rule {
  id: string;
  description: string;
  status?: "compliant" | "violated" | "unknown";
  clauses?: Clause[];
  measures?: string[];
  data?: Record<string, unknown>;
}

/**
 * A measure reference with an instruction for a specific level direction.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️levelmeasureref](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/LevelMeasureRef)
 *MUST have id and optional instruction.
 **/
interface LevelMeasureRef {
  id: string;
  instruction?: string;
}

/**
 * A level within a property, optionally with measures and instructions for raising/lowering.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️level](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Level)
 *MUST have a value. May have measures (lower/higher) and instructions (higher).
 **/
interface Level {
  value: string;
  name?: string;
  description?: string;
  measures?: { lower?: LevelMeasureRef[]; higher?: LevelMeasureRef[] };
  instructions?: { higher?: LevelMeasureRef[] };
}

/**
 * A property definition on a framework.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️property](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Property)
 *MUST have id and name.
 **/
interface Property {
  id: string;
  name?: string;
  type?: string;
  description?: string;
  url?: string;
  levels?: Level[];
}

/**
 * A compliance framework with properties and rules. General (not project-scoped).
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️framework](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Framework)
 *MUST have an id.
 **/
interface Framework {
  id: string;
  properties?: Property[];
  rules?: Rule[];
}

/**
 * Project configuration from .coda/project.json.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️project](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Project)
 *MUST have design and targets.
 **/
interface Project {
  design?: { id: string; mcp?: Record<string, unknown> };
  targets?: Array<{ id: string; llm?: unknown[] }>;
  error?: string;
}

/**
 * Run metadata.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️run](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Run)
 *MUST have an id.
 **/
interface Run {
  id?: string;
  started?: string;
  run_id?: string;
  error?: string;
}

/**
 * Iteration metadata.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️iteration](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Iteration)
 *MUST have an index.
 **/
interface Iteration {
  index?: number | string;
  targets?: string[];
  error?: string;
}

/**
 * Compliance report from an iteration.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️report](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Report)
 *MUST contain rules array.
 **/
interface Report {
  rules?: Rule[];
  breachs?: Rule[];
  error?: string;
}

/**
 * Navigation page identifiers.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖types🛠️page](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Types/d/i/Page)
 *MUST enumerate all navigable pages.
 **/
type Page = "dashboard" | "config" | "runs" | "report" | "translations" | "actions" | "events";

// #endregion 🔖Types

// #region 🔖Helpers
// [🔬coda🖱️desktop💻renderer🔖renderer🔖helpers](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Helpers)
// Helper functions for parsing MCP responses and formatting data.
// Helpers MUST safely extract data from MCP JSON-RPC responses.

/**
 * Extract parsed JSON from an MCP resource response.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖helpers🛠️parsemcpresource](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Helpers/d/i/parseMcpResource)
 *MUST return null when the response has no valid content.
 **/
function parseMcpResource<T>(response: McpResponse): T | null {
  try {
    if (response.error) return null;
    const contents = response.result?.contents;
    if (contents && contents.length > 0 && contents[0].text) {
      return JSON.parse(contents[0].text) as T;
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * Extract parsed JSON from an MCP tool response.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖helpers🛠️parsemcptool](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Helpers/d/i/parseMcpTool)
 *MUST return null when the response has no valid content.
 **/
function parseMcpTool<T>(response: McpResponse): T | null {
  try {
    if (response.error) return null;
    const content = response.result?.content;
    if (content && content.length > 0 && content[0].text) {
      return JSON.parse(content[0].text) as T;
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * Format a timestamp or ID string for display.
// [🔬coda🖱️desktop💻renderer🔖renderer🔖helpers🛠️formatid](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Helpers/d/i/formatId)
 *MUST return a human-readable string.
 **/
function formatId(id: string | undefined): string {
  if (!id) return "—";
  return id.replace(/_/g, " ").replace(/-/g, " ");
}

// #endregion 🔖Helpers

// #region 🔖Icons
// [🔬coda🖱️desktop💻renderer🔖renderer🔖icons](composerepo://p/r/coda/b/u/desktop/f/renderer.tsx/s/Renderer/s/Icons)
// Inline SVG icon components used across the coda desktop UI.
// Icons MUST be pure functional components with className prop.

function IconDashboard({ className = "w-4 h-4" }: { className?: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="3" y="3" width="7" height="7" />
