      />
      <div className="flex justify-end">
        <Button onClick={handleSubmit} variant="primary" loading={loading === "Manual Save Report"} disabled={disabled || !input.trim()} className="text-xs">
          Save Report
        </Button>
      </div>
    </div>
  );
}

