        console.log("[DEBUG] DOM snapshot saved to /tmp/coda-desktop-dom.html");
      } catch (e) {
        console.error("[DEBUG] Screenshot/DOM capture failed:", e);
      }
    }, 5000);
  });
};

app.on("ready", () => {
  if (currentProjectPath) {
    startSidecar();
  }
  createWindow();
});

app.on("window-all-closed", () => {
