        const pngBuffer = image.toPNG();
        const screenshotPath = "/tmp/coda-desktop-screenshot.png";
        fs.writeFileSync(screenshotPath, pngBuffer);
        console.log(`[DEBUG] Screenshot saved to ${screenshotPath} (${pngBuffer.length} bytes)`);
        const html = await mainWindow.webContents.executeJavaScript("document.documentElement.outerHTML.substring(0, 5000)");
        fs.writeFileSync("/tmp/coda-desktop-dom.html", html);
        console.log("[DEBUG] DOM snapshot saved to /tmp/coda-desktop-dom.html");
      } catch (e) {
        console.error("[DEBUG] Screenshot/DOM capture failed:", e);
      }
    }, 5000);
  });
};

