// [DEBUG] Capture screenshot and page HTML after load
mainWindow.webContents.on("did-finish-load", () => {
  setTimeout(async () => {
    try {
      const html = await mainWindow.webContents.executeJavaScript("document.getElementById('root').innerHTML.substring(0, 10000)");
      fs.writeFileSync("/tmp/coda-desktop-dom.html", html);
      console.log(`[DEBUG] DOM snapshot saved (${html.length} chars)`);
      const styles = await mainWindow.webContents.executeJavaScript(`
        JSON.stringify({
          rootChildren: document.getElementById('root').children.length,
          bodyBg: getComputedStyle(document.body).backgroundColor,
          bodyColor: getComputedStyle(document.body).color,
          rootBg: getComputedStyle(document.getElementById('root')).backgroundColor,
          firstChild: document.getElementById('root').firstElementChild?.tagName,
          firstChildClasses: document.getElementById('root').firstElementChild?.className,
          firstChildBg: document.getElementById('root').firstElementChild ? getComputedStyle(document.getElementById('root').firstElementChild).backgroundColor : 'none',
          firstChildDisplay: document.getElementById('root').firstElementChild ? getComputedStyle(document.getElementById('root').firstElementChild).display : 'none',
          firstChildVisibility: document.getElementById('root').firstElementChild ? getComputedStyle(document.getElementById('root').firstElementChild).visibility : 'none',
          firstChildHeight: document.getElementById('root').firstElementChild ? getComputedStyle(document.getElementById('root').firstElementChild).height : 'none',
          windowVar: getComputedStyle(document.documentElement).getPropertyValue('--window'),
          foregroundVar: getComputedStyle(document.documentElement).getPropertyValue('--foreground'),
          stylesheetCount: document.styleSheets.length,
        })
      `);
      console.log(`[DEBUG] Computed styles: ${styles}`);
      const image = await mainWindow.webContents.capturePage();
      const pngBuffer = image.toPNG();
      fs.writeFileSync("/tmp/coda-desktop-screenshot.png", pngBuffer);
      console.log(`[DEBUG] Screenshot saved (${pngBuffer.length} bytes)`);
    } catch (e) {
      console.error("[DEBUG] Capture failed:", e);
    }
  }, 8000);
});

