    const prefix = level === 3 ? "ERROR" : level === 2 ? "WARN" : "LOG";
    console.log(`[DEBUG] renderer [${prefix}]: ${message}`);
  });
  mainWindow.webContents.on("render-process-gone", (_e, details) => {
    console.error(`[DEBUG] render-process-gone:`, details);
  });
  mainWindow.webContents.on("unresponsive", () => {
    console.error(`[DEBUG] renderer unresponsive`);
  });
  // [DEBUG] Capture screenshot and page HTML after load
  mainWindow.webContents.on("did-finish-load", () => {
    // Inject error catcher immediately
    mainWindow.webContents
      .executeJavaScript(
        `
      window.addEventListener('error', (e) => console.error('[DEBUG] Uncaught error:', e.message, e.filename, e.lineno));
      window.addEventListener('unhandledrejection', (e) => console.error('[DEBUG] Unhandled rejection:', e.reason));
      console.log('[DEBUG] Error handlers installed');
    `,
      )
      .catch((e) => console.error("[DEBUG] Failed to inject error handlers:", e));

    setTimeout(async () => {
      try {
        const diag = await mainWindow.webContents.executeJavaScript(`
          JSON.stringify({
            rootChildren: document.getElementById('root')?.children.length ?? -1,
            stylesheetCount: document.styleSheets.length,
            allResources: performance.getEntriesByType('resource').map(e => e.name.replace('http://localhost:5173','').replace('http://127.0.0.1:5173','')),
          })
        `);
        console.log("[DEBUG] Page diagnostics:", diag);
        const image = await mainWindow.webContents.capturePage();
        fs.writeFileSync("/tmp/coda-desktop-screenshot.png", image.toPNG());
        console.log("[DEBUG] Screenshot saved");
      } catch (e) {
        console.error("[DEBUG] Capture failed:", e);
      }
    }, 45000);
  });
};

app.on("ready", () => {
  if (currentProjectPath) {
    startSidecar();
  }
  createWindow();
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
    stopSidecar();
    app.quit();
  }
});

app.on("activate", () => {
  if (BrowserWindow.getAllWindows().length === 0) {
    createWindow();
  }
});

app.on("before-quit", () => {
  stopSidecar();
});

