                                                </div>
                                              ))}
                                            </div>
                                          </div>
                                        )}
                                      </div>
                                    )}
                                    {level.instructions && level.instructions.higher && level.instructions.higher.length > 0 && (
                                      <div className="space-y-1 pl-2 border-l-2 border-border-window">
