// [🔬coda🖱️desktop💻main🔖mainprocess](composerepo://p/r/coda/b/u/desktop/f/main.ts/s/Main%20Process)
// Electron main process that creates the browser window and registers IPC handlers.
// MUST quit on all windows closed except on macOS.

/**
 * Creates the main Electron browser window with preload and vite integration.
// [🔬coda🖱️desktop💻main🔖mainprocess🛠️createwindow](composerepo://p/r/coda/b/u/desktop/f/main.ts/s/Main%20Process/d/i/createWindow)
 *
 * MUST load the vite dev server URL in development and the built file in production.
 **/
const createWindow = () => {
  const mainWindow = new BrowserWindow({
    width: 1200,
    height: 800,
    autoHideMenuBar: true,
    frame: false,
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
    },
  });

  if (MAIN_WINDOW_VITE_DEV_SERVER_URL) {
    // Retry loading with backoff to handle Vite dev server startup race
    const loadWithRetry = async (retries = 5, delay = 1000) => {
      for (let i = 0; i < retries; i++) {
        try {
          await mainWindow.loadURL(MAIN_WINDOW_VITE_DEV_SERVER_URL);
          return;
        } catch {
          if (i < retries - 1) {
            console.log(`[coda desktop] Vite not ready, retrying in ${delay}ms... (${i + 1}/${retries})`);
            await new Promise((r) => setTimeout(r, delay));
            delay *= 2;
          }
        }
      }
    };
    loadWithRetry().then(() => {
      // [DEBUG] Capture diagnostic screenshot after modules load
      setTimeout(async () => {
        try {
          const rootChildren = await mainWindow.webContents.executeJavaScript("document.getElementById('root')?.children.length ?? -1");
          const styleCount = await mainWindow.webContents.executeJavaScript("document.styleSheets.length");
          console.log(`[DEBUG] renderer state: rootChildren=${rootChildren}, styleSheets=${styleCount}`);
          const image = await mainWindow.webContents.capturePage();
          fs.writeFileSync("/tmp/coda-desktop-screenshot.png", image.toPNG());
          console.log("[DEBUG] Screenshot saved to /tmp/coda-desktop-screenshot.png");
        } catch (e) {
          console.error("[DEBUG] Diagnostic failed:", e);
        }
      }, 20000);
    });
  } else {
    mainWindow.loadFile(path.join(__dirname, `../renderer/${MAIN_WINDOW_VITE_NAME}/index.html`));
  }
};

app.on("ready", () => {
  if (currentProjectPath) {
    startSidecar();
  }
  createWindow();
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
    stopSidecar();
    app.quit();
  }
});

