    // Pre-warm the Vite module graph by fetching the renderer entry point.
    // This forces Vite to transform the entire dependency chain (elements.tsx
    // barrel imports 34+ packages) and cache the results BEFORE Electron's
    // Chromium renderer requests them. Without this, the 80+ ESM module
    // waterfall stalls under Chromium's 6-connection-per-origin HTTP/1.1 limit.
    const warmupUrl = MAIN_WINDOW_VITE_DEV_SERVER_URL.replace(/\/$/, "") + "/renderer.tsx";
    console.log(`[coda desktop] Pre-warming Vite module graph: ${warmupUrl}`);
    await new Promise<void>((resolve) => {
      const url = new URL(warmupUrl);
      const client = url.protocol === "https:" ? require("node:https") : require("node:http");
      const req = client.get(warmupUrl, (res: { resume: () => void; on: (event: string, cb: () => void) => void }) => {
        res.resume();
        res.on("end", () => {
          console.log("[coda desktop] Vite module graph warm.");
          resolve();
        });
      });
      req.on("error", () => {
        console.log("[coda desktop] Vite warmup request failed, proceeding anyway.");
        resolve();
      });
      req.setTimeout(60000, () => {
        req.destroy();
        console.log("[coda desktop] Vite warmup timed out after 60s, proceeding anyway.");
        resolve();
      });
    });

    // Retry loading with backoff to handle Vite dev server startup race
    const loadWithRetry = async (retries = 5, delay = 1000) => {
      for (let i = 0; i < retries; i++) {
        try {
          await mainWindow.loadURL(MAIN_WINDOW_VITE_DEV_SERVER_URL);
          return;
        } catch {
          if (i < retries - 1) {
            console.log(`[coda desktop] Vite not ready, retrying in ${delay}ms... (${i + 1}/${retries})`);
            await new Promise((r) => setTimeout(r, delay));
            delay *= 2;
          }
        }
      }
    };
    await loadWithRetry();
  } else {
    mainWindow.loadFile(path.join(__dirname, `../renderer/${MAIN_WINDOW_VITE_NAME}/index.html`));
  }
};

