// Vite build configuration for the Electron renderer process.
// Pre-bundles all dependencies from elements.tsx to prevent module waterfall
// stalls in Electron's HTTP/1.1 connection-limited renderer.

// #endregion 🔖Header

// #region 🔖Configuration
// [🔬coda🖱️desktop⚙️viterendererconfig🔖configuration](composerepo://p/r/coda/b/u/desktop/f/vite.renderer.config.ts/s/Configuration)
// Vite configuration for the Electron renderer process with React and Tailwind.
// Configuration MUST enable the React and Tailwind CSS plugins.
// Configuration MUST pre-bundle heavy dependencies to avoid white screen in Electron.

import type { UserConfig } from "vite";
import react from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";
import path from "path";

const configuration: UserConfig = {
  server: {
    // Pre-transform the renderer entry so all modules are cached before
    // Electron requests them. Without this, cold starts produce a white screen
    // because Electron's Chromium has a 6-connection-per-origin HTTP/1.1 limit
    // and the 80+ ESM module waterfall from elements.tsx stalls.
    warmup: {
      clientFiles: ["./renderer.tsx"],
    },
  },
  optimizeDeps: {
    // Pre-bundle all third-party dependencies imported by elements.tsx into
    // single chunks. This reduces the number of HTTP requests from 80+ to ~35
    // pre-bundled files, preventing connection pool exhaustion in Electron.
    include: [
      "react",
      "react-dom",
      "react-dom/client",
      "react/jsx-runtime",
      "react/jsx-dev-runtime",
      "@dnd-kit/core",
      "@dnd-kit/sortable",
      "@dnd-kit/utilities",
      "@radix-ui/react-accordion",
      "@radix-ui/react-avatar",
      "@radix-ui/react-collapsible",
      "@radix-ui/react-dialog",
      "@radix-ui/react-dropdown-menu",
      "@radix-ui/react-hover-card",
      "@radix-ui/react-popover",
      "@radix-ui/react-scroll-area",
      "@radix-ui/react-select",
      "@radix-ui/react-slider",
      "@radix-ui/react-slot",
      "@radix-ui/react-tabs",
      "@radix-ui/react-toggle",
      "@radix-ui/react-toggle-group",
      "@radix-ui/react-tooltip",
      "@react-three/drei",
      "@react-three/fiber",
      "@xyflow/react",
      "class-variance-authority",
      "clsx",
      "cmdk",
      "d3-force",
      "dagre",
      "fuse.js",
      "react-i18next",
      "react-resizable-panels",
      "react-router",
      "tailwind-merge",
      "three",
    ],
  },
  resolve: {
    alias: {
      "@compose/js": path.resolve(__dirname, "../../compose/js"),
      "@compose/assets": path.resolve(__dirname, "../../compose/assets"),
      "@elements/ui": path.resolve(__dirname, "../../elements/ui"),
      "@coda/desktop": path.resolve(__dirname, "."),
    },
  },
  plugins: [...(tailwindcss() as unknown as NonNullable<UserConfig["plugins"]>), react() as unknown as NonNullable<UserConfig["plugins"]>[number]],
};

export default configuration;

// #endregion 🔖Configuration

// #region 🔖Header
// [🔬coda🖱️desktop⚙️vitemainconfig](composerepo://p/r/coda/b/u/desktop/f/vite.main.config.ts)

// 2026 Ueli Saluz <ueli@compose-tech.de>

// This program is free software: you can redistribute it and/or modify
// it under the terms of the GNU Affero General Public License as
// published by the Free Software Foundation, either version 3 of the
// License, or (at your option) any later version.
// This program is distributed in the hope that it will be useful,
// but WITHOUT ANY WARRANTY; without even the implied warranty of
// MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the
// GNU Affero General Public License for more details.
// You should have received a copy of the GNU Affero General Public License
// along with this program.  If not, see <https://www.gnu.org/licenses/>.

// Vite build configuration for the Electron main process.

// #endregion 🔖Header

// #region 🔖Configuration
// [🔬coda🖱️desktop⚙️vitemainconfig🔖configuration](composerepo://p/r/coda/b/u/desktop/f/vite.main.config.ts/s/Configuration)
// Vite configuration for the Electron main process.
// Configuration MUST export a valid Vite config object.

import { defineConfig } from "vite";
import { builtinModules } from "module";

export default defineConfig({
  build: {
    outDir: ".vite/build",
    lib: {
      entry: "main.ts",
      formats: ["cjs"],
      fileName: () => "main.js",
    },
    rollupOptions: {
