// [🔬coda🖱️desktop💻main🔖mainprocess](composerepo://p/r/coda/b/u/desktop/f/main.ts/s/Main%20Process)
// Electron main process that creates the browser window and registers IPC handlers.
// MUST quit on all windows closed except on macOS.

/**
 * Creates the main Electron browser window with preload and vite integration.
// [🔬coda🖱️desktop💻main🔖mainprocess🛠️createwindow](composerepo://p/r/coda/b/u/desktop/f/main.ts/s/Main%20Process/d/i/createWindow)
 *
 * MUST load the vite dev server URL in development and the built file in production.
 **/
const createWindow = async () => {
  const mainWindow = new BrowserWindow({
    width: 1200,
    height: 800,
    autoHideMenuBar: true,
    frame: false,
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
    },
  });

  if (MAIN_WINDOW_VITE_DEV_SERVER_URL) {
    // Pre-warm the Vite module graph by fetching the renderer entry point.
    // This forces Vite to transform the entire dependency chain (elements.tsx
    // barrel imports 34+ packages) and cache the results BEFORE Electron's
    // Chromium renderer requests them. Without this, the 80+ ESM module
    // waterfall stalls under Chromium's 6-connection-per-origin HTTP/1.1 limit.
    const warmupUrl = MAIN_WINDOW_VITE_DEV_SERVER_URL.replace(/\/$/, "") + "/renderer.tsx";
    console.log(`[coda desktop] Pre-warming Vite module graph: ${warmupUrl}`);
    await new Promise<void>((resolve) => {
      const url = new URL(warmupUrl);
      const client = url.protocol === "https:" ? require("node:https") : require("node:http");
      const req = client.get(warmupUrl, (res: { resume: () => void; on: (event: string, cb: () => void) => void }) => {
        res.resume();
        res.on("end", () => {
          console.log("[coda desktop] Vite module graph warm.");
          resolve();
        });
      });
      req.on("error", () => {
        console.log("[coda desktop] Vite warmup request failed, proceeding anyway.");
        resolve();
      });
      req.setTimeout(60000, () => {
        req.destroy();
        console.log("[coda desktop] Vite warmup timed out after 60s, proceeding anyway.");
        resolve();
      });
    });

    // Retry loading with backoff to handle Vite dev server startup race
    const loadWithRetry = async (retries = 5, delay = 1000) => {
      for (let i = 0; i < retries; i++) {
        try {
          await mainWindow.loadURL(MAIN_WINDOW_VITE_DEV_SERVER_URL);
          return;
        } catch {
          if (i < retries - 1) {
            console.log(`[coda desktop] Vite not ready, retrying in ${delay}ms... (${i + 1}/${retries})`);
            await new Promise((r) => setTimeout(r, delay));
            delay *= 2;
          }
        }
      }
    };
    await loadWithRetry();

    // [DEBUG] Check renderer console errors and module loading state
    mainWindow.webContents.on("console-message", (_event: unknown, level: number, message: string) => {
      console.log(`[DEBUG] renderer console [${level}]: ${message.substring(0, 500)}`);
    });
    mainWindow.webContents.on("did-fail-load" as string, (_event: unknown, code: number, desc: string, url: string) => {
      console.log(`[DEBUG] did-fail-load: code=${code} desc=${desc} url=${url}`);
    });
    mainWindow.webContents.on("render-process-gone" as string, (_event: unknown, details: unknown) => {
      console.log(`[DEBUG] render-process-gone:`, details);
    });
    // Inject error catchers before any modules load
    mainWindow.webContents.on("dom-ready" as string, async () => {
      console.log("[DEBUG] dom-ready fired");
      await mainWindow.webContents.executeJavaScript(`
        window.__moduleErrors = [];
        window.addEventListener('error', (e) => {
          console.error('[MODULE ERROR]', e.message, e.filename, e.lineno);
          window.__moduleErrors.push({msg: e.message, file: e.filename, line: e.lineno});
        });
        window.addEventListener('unhandledrejection', (e) => {
          console.error('[UNHANDLED REJECTION]', e.reason?.message || e.reason);
          window.__moduleErrors.push({msg: String(e.reason?.message || e.reason)});
        });
      `);
    });
    // [DEBUG] Test dynamic import after 30s to see if module evaluation works
    setTimeout(async () => {
      try {
        const resourceCount = await mainWindow.webContents.executeJavaScript(`performance.getEntriesByType('resource').length`);
        const rootChildren = await mainWindow.webContents.executeJavaScript(`document.getElementById('root')?.children.length ?? -1`);
        const styleSheets = await mainWindow.webContents.executeJavaScript(`document.styleSheets.length`);
        console.log(`[DEBUG] state: resources=${resourceCount} rootChildren=${rootChildren} styles=${styleSheets}`);

        // Try dynamic import to see what happens
        const importResult = await mainWindow.webContents.executeJavaScript(`
          (async () => {
            try {
              const mod = await import('/renderer.tsx');
              return 'SUCCESS: keys=' + Object.keys(mod).join(',');
            } catch(e) {
              return 'FAIL: ' + e.message + ' | stack: ' + (e.stack || '').substring(0, 1000);
            }
          })()
        `);
        console.log("[DEBUG] dynamic import:", importResult);

        const image = await mainWindow.webContents.capturePage();
        fs.writeFileSync("/tmp/coda-desktop-screenshot.png", image.toPNG());
        console.log("[DEBUG] Screenshot saved");
      } catch (e) {
        console.error("[DEBUG] Diagnostic failed:", e);
      }
    }, 30000);
  } else {
    mainWindow.loadFile(path.join(__dirname, `../renderer/${MAIN_WINDOW_VITE_NAME}/index.html`));
  }
};

